import{_ as r,o as n,c as o,a2 as a}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"🔧 04 · 微调技术（Fine-Tuning & PEFT）","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/04-微调技术.md","filePath":"01-算法岗-AIGC与LLM/04-微调技术.md","lastUpdated":1786806808000}'),e={name:"01-算法岗-AIGC与LLM/04-微调技术.md"};function i(l,t,d,s,u,h){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="🔧-04-·-微调技术-fine-tuning-peft" tabindex="-1">🔧 04 · 微调技术（Fine-Tuning &amp; PEFT） <a class="header-anchor" href="#🔧-04-·-微调技术-fine-tuning-peft" aria-label="Permalink to &quot;🔧 04 · 微调技术（Fine-Tuning &amp; PEFT）&quot;">​</a></h1><blockquote><p>预训练给「通才」，微调给「专才」。本篇讲全参微调与高效微调（LoRA 是必考）。</p></blockquote><hr><h2 id="一、为什么需要微调" tabindex="-1">一、为什么需要微调？ <a class="header-anchor" href="#一、为什么需要微调" aria-label="Permalink to &quot;一、为什么需要微调？&quot;">​</a></h2><p>预训练模型懂通用语言，但不知你的<strong>任务格式/领域知识/风格</strong>。微调用<strong>任务数据</strong>调整参数，使其适配下游。</p><hr><h2 id="二、全参微调-full-fine-tuning" tabindex="-1">二、全参微调（Full Fine-Tuning） <a class="header-anchor" href="#二、全参微调-full-fine-tuning" aria-label="Permalink to &quot;二、全参微调（Full Fine-Tuning）&quot;">​</a></h2><p>更新全部参数。效果上限最高，但：</p><ul><li>显存/算力开销大（需存优化器状态）</li><li>易灾难性遗忘（Catastrophic Forgetting）</li><li>每个任务存一份全量权重，成本高</li></ul><hr><h2 id="三、peft-参数高效微调-家族" tabindex="-1">三、PEFT（参数高效微调）家族 <a class="header-anchor" href="#三、peft-参数高效微调-家族" aria-label="Permalink to &quot;三、PEFT（参数高效微调）家族&quot;">​</a></h2><p>只训练少量参数，冻结主干。代表：</p><table tabindex="0"><thead><tr><th>方法</th><th>思路</th><th>参数量</th></tr></thead><tbody><tr><td><strong>LoRA</strong></td><td>低秩分解增量 $\\Delta W = BA$</td><td>极少（~0.1-1%）</td></tr><tr><td><strong>QLoRA</strong></td><td>LoRA + 4-bit 量化主干</td><td>单卡可训</td></tr><tr><td><strong>Adapter</strong></td><td>插入小前馈瓶颈层</td><td>少</td></tr><tr><td><strong>Prefix-Tuning</strong></td><td>在输入前加可训练前缀向量</td><td>少</td></tr><tr><td><strong>Prompt-Tuning</strong></td><td>只调软提示 embedding</td><td>极少</td></tr></tbody></table><hr><h2 id="四、lora-原理-⭐-必考-能手推-⭐" tabindex="-1">四、LoRA 原理（⭐ 必考，能手推）⭐ <a class="header-anchor" href="#四、lora-原理-⭐-必考-能手推-⭐" aria-label="Permalink to &quot;四、LoRA 原理（⭐ 必考，能手推）⭐&quot;">​</a></h2><p><strong>核心</strong>：权重更新 $\\Delta W$ 是<strong>低秩</strong>的。对原权重 $W \\in \\mathbb{R}^{d\\times k}$，不直训 $W$，而是：</p><p>$$W&#39; = W + \\Delta W = W + BA,\\quad B\\in\\mathbb{R}^{d\\times r},\\ A\\in\\mathbb{R}^{r\\times k},\\ r \\ll \\min(d,k)$$</p><ul><li>训练时只更新 $A,B$，参数量从 $d\\times k$ 降到 $r(d+k)$。</li><li>例：d=k=4096, r=8 → 原 16.7M 参数 → 现 65K，<strong>缩减 ~256 倍</strong>。</li><li>推理时可把 $BA$ 加回 $W$（merge），<strong>零额外延迟</strong>。</li></ul><p><strong>为什么低秩有效？</strong> 观测表明大模型权重更新的「内在秩」很低，少量维度即可捕捉任务增量。</p><p><strong>超参</strong>：rank $r$（通常 8/16/32/64）、alpha（缩放）、target_modules（通常 q,v 或 q,k,v,o）。</p><hr><h2 id="五、指令微调-instruction-tuning-sft" tabindex="-1">五、指令微调（Instruction Tuning / SFT） <a class="header-anchor" href="#五、指令微调-instruction-tuning-sft" aria-label="Permalink to &quot;五、指令微调（Instruction Tuning / SFT）&quot;">​</a></h2><p>用「指令-回答」格式数据训练，让模型学会<strong>遵循指令</strong>而非仅续写。是 Chat 模型的关键一步。</p><ul><li>数据来源：人工标注、Self-Instruct 合成、蒸馏（用强模型造弱模型训练数据）</li><li>与「对齐」的关系：SFT 是「能力」解锁，RLHF/DPO 是「偏好」对齐（见 <code>05-对齐技术</code>）。</li></ul><hr><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：LoRA 和全参微调怎么选？</strong></p><blockquote><p>资源有限/多任务（一个主干挂多个 LoRA）/防遗忘 → LoRA。追求极限效果且资源充足 → 全参。多数工业场景 LoRA 够用。</p></blockquote><p><strong>Q2：LoRA 的 rank 越大越好吗？</strong></p><blockquote><p>不一定。rank 太小欠拟合，太大逼近全参微调且失效率优势；需按任务调，常用 8-64。</p></blockquote><p><strong>Q3：QLoRA 怎么做到单卡训大模型？</strong></p><blockquote><p>主干 4-bit NF4 量化（省显存）+ 分页优化器 + LoRA 只训少量参数，使 65B 模型可在单张 48G 卡上微调。</p></blockquote><p><strong>Q4：怎么缓解灾难性遗忘？</strong></p><blockquote><p>PEFT（冻主干）、Replay（混入预训练数据）、参数正则（EWC）、低学习率。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-对齐技术">05-对齐技术</a></p>',36)])])}const c=r(e,[["render",i]]);export{g as __pageData,c as default};
